module tb;
    reg do_sub;
    reg [7:0] a, b;
    wire [7:0] out;
    wire result_is_zero;

    TopModule dut (
        .do_sub(do_sub),
        .a(a),
        .b(b),
        .out(out),
        .result_is_zero(result_is_zero)
    );

    initial begin
        // Test 1: Addition, non-zero result
        do_sub = 0;
        a = 8'd5;
        b = 8'd3;
        #10;
        if (out !== 8'd8 || result_is_zero !== 1'b0) begin
            $display("SELFTEST FAIL: Test 1 failed. out=%0d (expected 8), zero=%0b (expected 0)", out, result_is_zero);
            $finish;
        end

        // Test 2: Addition, zero result (e.g., 0 + 0)
        a = 8'd0;
        b = 8'd0;
        #10;
        if (out !== 8'd0 || result_is_zero !== 1'b1) begin
            $display("SELFTEST FAIL: Test 2 failed. out=%0d (expected 0), zero=%0b (expected 1)", out, result_is_zero);
            $finish;
        end

        // Test 3: Subtraction, non-zero result
        do_sub = 1;
        a = 8'd10;
        b = 8'd4;
        #10;
        if (out !== 8'd6 || result_is_zero !== 1'b0) begin
            $display("SELFTEST FAIL: Test 3 failed. out=%0d (expected 6), zero=%0b (expected 0)", out, result_is_zero);
            $finish;
        end

        // Test 4: Subtraction, zero result (10 - 10)
        a = 8'd10;
        b = 8'd10;
        #10;
        if (out !== 8'd0 || result_is_zero !== 1'b1) begin
            $display("SELFTEST FAIL: Test 4 failed. out=%0d (expected 0), zero=%0b (expected 1)", out, result_is_zero);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
